[DataContract]
class OMGTutorialLedgerJournalLineDataContract
{        
    LedgerJournalTransTxt   text;   
    TransDate               transDate;    
    AmountCurDebit          debitAmount;
    DimensionDisplayValue   accountDisplayValue;
    LedgerJournalACType     accountType;
    AmountCurCredit         creditAmount;
    CurrencyCode            currencyCode;
    InvoiceId               invoiceId;
    DueDate                 dueDate;    
    PaymTermId              paymTermId;
    TaxItemGroup            itemSalesTaxGroup;    
    TaxGroupJournal         salesTaxGroup;

}

